<?php
require_once dirname(__DIR__).'/repositories/userPDO.php';
function validateIdentity(string $name,string $email): array { $errors=[];if((function_exists('mb_strlen') ? mb_strlen(trim($name)) : strlen(trim($name)))<2||(function_exists('mb_strlen') ? mb_strlen(trim($name)) : strlen(trim($name)))>120)$errors[]='Name must contain 2 to 120 characters.';if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($email)>254)$errors[]='Enter a valid email.';return $errors; }
function validatePassword(string $password): array {return strlen($password)<12 ? ['Password must contain at least 12 characters.'] : [];}
function registerUser(PDO $pdo,array $input): int {
 $name=trim((string)($input['full_name']??''));$email=strtolower(trim((string)($input['email']??'')));$password=(string)($input['password']??'');$role=(string)($input['role']??'');
 $errors=array_merge(validateIdentity($name,$email),validatePassword($password));if($password!==($input['confirm_password']??null))$errors[]='Passwords do not match.';if(!in_array($role,['Student','Tutor'],true))$errors[]='Only Student or Tutor registration is allowed.';
 if($errors)throw new InvalidArgumentException(implode(' ',$errors));
 if(findUserByEmail($pdo,$email))throw new InvalidArgumentException('Email is already registered.');
 $pdo->beginTransaction();try{$id=insertUser($pdo,$name,$email,password_hash($password,PASSWORD_DEFAULT),$role);if($role==='Student'){$s=$pdo->prepare('INSERT INTO students(student_name,student_email,user_id) VALUES(?,?,?)');$s->execute([$name,$email,$id]);}$pdo->commit();return $id;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();if($e instanceof PDOException && $e->getCode()==='23000')throw new InvalidArgumentException('Email already exists or conflicts with a student record.');throw $e;}
}
function authenticateUser(PDO $pdo,string $email,string $password) { $u=findUserByEmail($pdo,$email);return $u && $u['status']==='Active' && password_verify($password,$u['password_hash'])?$u:false; }
function changeOwnProfile(PDO $pdo,int $id,string $name,string $email): void { $name=trim($name);$email=strtolower(trim($email));$errors=validateIdentity($name,$email);if($errors)throw new InvalidArgumentException(implode(' ',$errors));$u=findUserById($pdo,$id);if(!$u)throw new InvalidArgumentException('Account not found.');$other=findUserByEmail($pdo,$email);if($other && (int)$other['user_id']!==$id)throw new InvalidArgumentException('Email already registered.');$pdo->beginTransaction();try{updateUserProfile($pdo,$id,$name,$email);if($u['role']==='Student'){$s=$pdo->prepare('UPDATE students SET student_name=?,student_email=? WHERE user_id=?');$s->execute([$name,$email,$id]);}$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;} }
function changeOwnPassword(PDO $pdo,int $id,string $old,string $new,string $confirm): void { $u=findUserById($pdo,$id);if(!$u||!password_verify($old,$u['password_hash']))throw new InvalidArgumentException('Current password is incorrect.');$errors=validatePassword($new);if($new!==$confirm)$errors[]='Passwords do not match.';if($errors)throw new InvalidArgumentException(implode(' ',$errors));updateUserPassword($pdo,$id,password_hash($new,PASSWORD_DEFAULT)); }
function activeAdministratorCount(PDO $pdo): int {return (int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='Administrator' AND status='Active'")->fetchColumn();}
function adminChangeRole(PDO $pdo,int $target,string $role): void {if(!in_array($role,['Student','Tutor','Administrator'],true))throw new InvalidArgumentException('Invalid role.');$u=findUserById($pdo,$target);if(!$u)throw new InvalidArgumentException('Account not found.');if($u['role']==='Administrator' && $u['status']==='Active' && $role!=='Administrator' && activeAdministratorCount($pdo)<=1)throw new InvalidArgumentException('Cannot remove the last active administrator.');if($u['role']==='Student' && $role!=='Student'){$s=$pdo->prepare('SELECT COUNT(*) FROM tutoring_requests r JOIN students st ON r.student_id=st.student_id WHERE st.user_id=?');$s->execute([$target]);if($s->fetchColumn()>0)throw new InvalidArgumentException('Student with tutoring requests cannot change role.');} $pdo->beginTransaction();try{updateUserField($pdo,$target,'role',$role);if($role==='Student' && $u['role']!=='Student'){$s=$pdo->prepare('INSERT INTO students(student_name,student_email,user_id) VALUES(?,?,?)');$s->execute([$u['full_name'],$u['email'],$target]);}if($u['role']==='Student'&&$role!=='Student'){$s=$pdo->prepare('DELETE FROM students WHERE user_id=?');$s->execute([$target]);}$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;} }
function adminChangeStatus(PDO $pdo,int $target,string $status): void {if(!in_array($status,['Active','Inactive'],true))throw new InvalidArgumentException('Invalid status.');$u=findUserById($pdo,$target);if(!$u)throw new InvalidArgumentException('Account not found.');if($u['role']==='Administrator' && $u['status']==='Active' && $status==='Inactive' && activeAdministratorCount($pdo)<=1)throw new InvalidArgumentException('Cannot deactivate the last active administrator.');updateUserField($pdo,$target,'status',$status);}
function adminDeleteUser(PDO $pdo,int $target): void {throw new DomainException('Permanent deletion is disabled pending approval of the retention policy (UM-08).');}
